The binary search is implemented as:
https://github.com/rust-lang/rust/blob/27e766d7bc84be992c8ddef710affc92ef4a0adf/src/libcore/slice.rs#L304-L324

Here I've added a caller to instantiate it with commonly used types (u32 and its cmp):

```rust
use std::cmp::Ordering::{self, *};

fn binary_search_by<T, F>(this: &[T], mut f: F) -> Result<usize, usize> where
        F: FnMut(&T) -> Ordering
    {
        let mut base = 0usize;
        let mut s = this;

        loop {
            let (head, tail) = s.split_at(s.len() >> 1);
            if tail.is_empty() {
                return Err(base)
            }
            match f(&tail[0]) {
                Less => {
                    base += head.len() + 1;
                    s = &tail[1..];
                }
                Greater => s = head,
                Equal => return Ok(base + head.len()),
            }
        }
}

pub fn foo(data: &[u32], x: u32) -> Result<usize, usize> {
    binary_search_by(data, |y| x.cmp(y))
}
```

rustc 1.54.0-nightly with optimizations gives:

```asm
foo:
	mov     r11, rsi
	shr     r11
	mov     eax, 1
	sub     rsi, r11
	je      .LBB0_8
	mov     r8d, edx
	lea     r10, [rdi + 4*r11]
	xor     edx, edx
	mov     r9, -1
	jmp     .LBB0_4
.LBB0_2:
	add     rdx, r11
	inc     rdx
	add     r10, 4
	dec     rsi
	mov     r11, rsi
	mov     rdi, r10
.LBB0_3:
	mov     rcx, r11
	shr     rcx
	lea     r10, [rdi + 4*rcx]
	sub     r11, rcx
	mov     rsi, r11
	mov     r11, rcx
	je      .LBB0_7
.LBB0_4:
	xor     ecx, ecx
	cmp     dword ptr [r10], r8d
	setne   cl
	cmova   rcx, r9
	cmp     rcx, -1
	je      .LBB0_2
	test    rcx, rcx
	jne     .LBB0_3
	add     rdx, r11
	xor     eax, eax
.LBB0_7:
	ret
.LBB0_8:
	xor     edx, edx
	ret
```

I've noticed that replacing the call to cmp + match with simpler code, the asm becomes shorter (6 asm instructions less):

```rust
fn binary_search_by<T: Ord>(this: &[T], x: T) -> Result<usize, usize> {
        let mut base = 0usize;
        let mut s = this;

        loop {
            let (head, tail) = s.split_at(s.len() >> 1);
            if tail.is_empty() {
                return Err(base)
            }
            if x < tail[0] {
                base += head.len() + 1;
                s = &tail[1 ..];
            } else if x > tail[0] {
                s = head;
            } else {
                return Ok(base + head.len());
            }
        }
}

pub fn foo(data: &[u32], x: u32) -> Result<usize, usize> {
    binary_search_by(data, x)
}
```

